    const CRN = {c:'#dfe9ee', glow:'#eaf4ff', gk:0.35};
    const P0 = RG[k].ring, cx = 0.1, cz = 0.0, Y0 = F + 14.5, YF = F + 196, YT = F + 236.5, YC = F + 243.5;
    // lobby / base on the real footprint
    prismP(B.p(LOB), P0, S.lo, Y0, true); corP(B.p(FIN), P0, Y0 - 0.6, 0.8, 0.2); mullP(B.p(FIN), P0, F, Y0 - 0.6, 1.8, 0.18, 0.05, null, 0.25);
    // shaft: rounded square, half size 15.2 -> 16.9 with the flare, corner radius 5.5 -> 1.2
    const sec = y => { const t = y <= YF ? 0 : Math.min(1, (y - YF)/(YT - YF)), f = t*t*(3 - 2*t)*0.75 + t*t*0.25, h = 15.2 + 1.75*f, r = 5.5 - 4.3*f; return rrectP(cx, cz, h, h, r, 5); };
    const ys = [Y0 - 0.5]; for (let y = Y0 + 10; y < YF; y += 30) ys.push(y); for (let i = 0; i <= 10; i++) ys.push(YF + (YT - YF)*i/10);
    const secs = ys.map(y => sec(y).map(p => [p[0], y, p[1]]));
    loftP(B.p(GL), secs, false);
    flatP(B.p(ROOF), sec(YT).map(p => p), YT - 1.5);
    // vertical fins: one every ~1.55 m round the perimeter following the flare
    const N = secs[0].length; { const o = B.p(FIN);
      for (let s = 0; s < secs.length - 1; s++){ const A = secs[s], Bq = secs[s + 1];
        // resample each section's perimeter at fixed fractions
        const res = R => { const L = [0]; for (let i = 0; i < R.length; i++){ const a = R[i], b = R[(i+1) % R.length]; L.push(L[i] + Math.hypot(b[0]-a[0], b[2]-a[2])); }
          const tot = L[L.length - 1], n = 72, out = []; let j = 0;
          for (let m = 0; m < n; m++){ const d = m/n*tot; while (L[j + 1] < d) j++; const a = R[j], b = R[(j+1) % R.length], u = (d - L[j])/((L[j+1] - L[j]) || 1); out.push([a[0] + (b[0]-a[0])*u, a[1], a[2] + (b[2]-a[2])*u]); }
          return out; };
        const ra = res(A), rb = res(Bq);
        for (let m = 0; m < ra.length; m++){ const a = ra[m], b = rb[m], na = Math.hypot(a[0] - cx, a[2] - cz) || 1, nb = Math.hypot(b[0] - cx, b[2] - cz) || 1, d = 0.32, w = 0.11;
          const ax = (a[0] - cx)/na, az = (a[2] - cz)/na, bx = (b[0] - cx)/nb, bz = (b[2] - cz)/nb;
          quadP(o, [a[0] - az*w, a[1], a[2] + ax*w], [a[0] + ax*d - az*w, a[1], a[2] + az*d + ax*w], [b[0] + bx*d - bz*w, b[1], b[2] + bz*d + bx*w], [b[0] - bz*w, b[1], b[2] + bx*w]); } } }
    // slab edges every 4 floors (subtle horizontal lines) and the crown screen above the roof
