    const BRK = '#7a4b3c', BRK2 = '#6b3f32', WIN = {c:'#2d3036', m:1, fh:4.3, cw:2.4}, CON = '#b7b0a3', ROOF = '#7d7b76', PAV = '#a9a397';
    const TP = RG[k].parts[0][2], tb = bbP(TP), X0 = tb[0], X1 = tb[2], Z0 = tb[1], Z1 = tb[3], cx = (X0 + X1)/2, cz = (Z0 + Z1)/2, HX = (X1 - X0)/2, HZ = (Z1 - Z0)/2;
    const YT = F + 59.5, FH = 4.25;
    // the cube's corners cantilever over the base: the lower floors are a cross in plan (corners cut away, stepping out
